const now = new Date();
const jstDate = new Date(now.getTime() + 9 * 3600000);
const dayOfYear = Math.floor((jstDate - new Date(jstDate.getFullYear(), 0, 0)) / 86400000);

const genres = [
  {
    name: '飲食業',
    description: '飲食店・カフェ・居酒屋などの個人店オーナー',
    themes: ['仕込み・調理の苦労', '接客あるある', '売上・集客の悩み', 'SNS運用のリアル', 'スタッフ管理', 'メニュー開発', '原価率・利益', '常連客との関係'],
    emoji: '🍽️'
  },
  {
    name: '美容サロン',
    description: '美容室・ネイル・まつ毛・エステなどの個人サロンオーナー',
    themes: ['予約管理のあるある', '技術練習の大変さ', 'カルテ・顧客管理', 'SNS集客のリアル', 'ドタキャン・無断キャンセル', '値上げの悩み', '道具・消耗品コスト', '常連様との関係'],
    emoji: '💇'
  },
  {
    name: '整体・マッサージ',
    description: '整体院・接骨院・マッサージ・リラクゼーションの個人店オーナー',
    themes: ['施術中のあるある', '腰痛・体の疲れのリアル', '口コミ・紹介の大切さ', '予約管理の悩み', 'リピーター定着の工夫', '道具メンテナンス', '患者様との信頼構築', '施術メニュー設計'],
    emoji: '🤲'
  }
];

const genre = genres[dayOfYear % 3];
const theme = genre.themes[dayOfYear % genre.themes.length];
const dateStr = `${jstDate.getFullYear()}-${String(jstDate.getMonth()+1).padStart(2,'0')}-${String(jstDate.getDate()).padStart(2,'0')}`;

return [{
  json: {
    genre: genre.name,
    description: genre.description,
    theme,
    emoji: genre.emoji,
    date: dateStr
  }
}];

const genre = $('業種を決定').first().json.genre;
const emoji = $('業種を決定').first().json.emoji;
const date = $('業種を決定').first().json.date;
const theme = $('業種を決定').first().json.theme;

// Anthropic APIレスポンスからテキストを取得
let text = '';
const content = $json.content;
if (Array.isArray(content)) {
  text = content.map(c => c.text || '').join('').trim();
}

if (!text) throw new Error('Claude からの投稿文が空です');

// 480字チェック
if (text.length > 480) {
  text = text.slice(0, 477) + '…';
}

return [{
  json: { text, genre, emoji, date, theme }
}];
